function nonce() { return [...Array(32)].map(() => Math.floor(Math.random() * 36).toString(36)).join(''); }
function escapeHtml(value) { return String(value).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
function backupsEnabled() { const config = vscode.workspace.getConfiguration('ikemenZss'); return false; }
function hostCapabilities() { return detectCapabilities({ uiKind: vscode.env.uiKind === vscode.UIKind.Web ? 'web' : 'desktop', platform: process.platform, environment: process.env }); }

function sffMutationOptions(filename, label, overrides = {}) {
  const resource = vscode.Uri.file(filename), config = vscode.workspace.getConfiguration('ikemenZss', resource);
  return optionsFromConfig(vscode, filename, label, {
    journalRoot: reviewStoreLocation(filename).root,
    backup: false,
    ...overrides
  });
}

function reviewStoreLocation(sffPath) {
  let current = path.dirname(sffPath);
  while (true) {
    if (fs.existsSync(path.join(current, 'Ikemen_GO.exe')) || fs.existsSync(path.join(current, 'external', 'script', 'main.lua'))) return { root: current, file: path.join(current, '.ikemen-tools', 'sff-review.json') };
    const parent = path.dirname(current); if (parent === current) break; current = parent;
  }
  const folder = (vscode.workspace.getWorkspaceFolder(vscode.Uri.file(sffPath)) || {}).uri;
  const root = folder ? folder.fsPath : path.dirname(sffPath);
  return { root, file: path.join(root, '.ikemen-tools', 'sff-review.json') };
}

function readReviewData(sffPath) {
  const location = reviewStoreLocation(sffPath), archiveKey = path.relative(location.root, sffPath).replace(/\\/g, '/');
  let store = { version: 1, archives: {} };
  if (fs.existsSync(location.file)) { try { store = JSON.parse(fs.readFileSync(location.file, 'utf8')); } catch (_) {} }
  if (!store.archives || typeof store.archives !== 'object') store.archives = {};
  const archive = store.archives[archiveKey] || { sprites: {} }; if (!archive.sprites) archive.sprites = {};
  return { location, archiveKey, store, archive };
}

function writeReviewRecord(sffPath, key, record) {
  const data = readReviewData(sffPath);
  if (!data.store.archives[data.archiveKey]) data.store.archives[data.archiveKey] = { sprites: {} };
  const sprites = data.store.archives[data.archiveKey].sprites || (data.store.archives[data.archiveKey].sprites = {});
  if ((!record.flags || !record.flags.length) && !String(record.note || '').trim() && !String(record.customName || '').trim()) delete sprites[key];
  else sprites[key] = { flags: [...new Set(record.flags || [])], note: String(record.note || '').trim(), customName: String(record.customName || '').trim(), updated: new Date().toISOString() };
  transactionalWrite(fs, data.location.file, `${JSON.stringify(data.store, null, 2)}\n`, sffMutationOptions(sffPath, 'sff-review-record'));
  return { record: sprites[key] || { flags: [], note: '' }, file: data.location.file };
}

function nearbyAirReferences(sffPath) {
  const directory = path.dirname(sffPath);
  const files = fs.readdirSync(directory).filter((name) => /\.air$/i.test(name));
  const references = new Map();
  for (const name of files) {
    const lines = fs.readFileSync(path.join(directory, name), 'utf8').split(/\r?\n/);
    let action = null;
    for (const raw of lines) {
      const line = raw.replace(/;.*/, '').trim();
      const heading = /^\[\s*begin\s+action\s+(-?\d+)\s*\]$/i.exec(line);
      if (heading) { action = Number(heading[1]); continue; }
      if (action === null || !line || line.startsWith('[')) continue;
      const frame = /^\s*(-?\d+)\s*,\s*(-?\d+)\s*,/.exec(line);
      if (!frame || Number(frame[1]) < 0 || Number(frame[2]) < 0) continue;
      const key = `${Number(frame[1])},${Number(frame[2])}`;
      if (!references.has(key)) references.set(key, []);
      const label = `${name}: Action ${action}`;
      if (!references.get(key).includes(label)) references.get(key).push(label);
    }
  }
  return references;
}

function nearbyAirAnimations(sffPath) {
  const directory = path.dirname(sffPath), animations = [];
  for (const name of fs.readdirSync(directory).filter((entry) => /\.air$/i.test(entry))) {
    let action = null;
    for (const raw of fs.readFileSync(path.join(directory, name), 'utf8').split(/\r?\n/)) {
      const line = raw.replace(/;.*/, '').trim(), heading = /^\[\s*begin\s+action\s+(-?\d+)\s*\]$/i.exec(line);
      if (heading) { action = { id: `${name}:${heading[1]}`, file: name, number: Number(heading[1]), frames: [], loopStart: 0 }; animations.push(action); continue; }
      if (!action || !line) continue;
      if (/^loopstart$/i.test(line)) { action.loopStart = action.frames.length; continue; }
      const parts = line.split(',').map((part) => part.trim());
      if (parts.length < 5 || parts.slice(0, 5).some((value) => !/^-?\d+$/.test(value))) continue;
      const group = Number(parts[0]), index = Number(parts[1]);
      if (group < 0 || index < 0) continue;
      action.frames.push({ group, index, x: Number(parts[2]), y: Number(parts[3]), time: Number(parts[4]), flags: (parts[5] || '').toUpperCase() });
    }
  }
  return animations.filter((action) => action.frames.length);
}

