  const assignPaletteButton=document.createElement('button');assignPaletteButton.id='assignPalette';assignPaletteButton.className='tool';assignPaletteButton.textContent='Assign to Matching Sprites…';assignPaletteButton.title='Assign the selected embedded palette within a chosen scope, but only to sprites currently sharing the active sprite palette; unrelated character, projectile, and FX palettes are skipped';assignPaletteButton.onclick=()=>vscode.postMessage({type:'assignPalette',paletteIndex:Number(document.getElementById('paletteSelect').value),sourcePaletteIndex:selected&&selected.paletteIndex,selectedIndex:selected&&selected.index,selectedIndices:[...selectedIndices],group:selected&&selected.group});document.getElementById('savePaletteEdits').parentElement.append(assignPaletteButton);
  const paletteLibrary=document.createElement('div');paletteLibrary.innerHTML='<hr><b>Project Palette Library</b><details id="paletteFolderHelp"><summary><b>How palette folders work</b></summary><div class="muted"><p><b>Source folders are complete working sets.</b> Keep one folder for Base and one for each form, such as SSB and SSBE. Use the same palette number in every applicable folder so <code>001</code> remains the same community color across forms.</p><p><b>Yes, put a duplicate indexed PNG in a form folder when that form does not change the color.</b> This keeps the source set complete and compatible with image-based Fighter Factory importing. During the SFF build, an identical form palette is preserved at its required RemapPal coordinate as a linked palette instead of wasting duplicate color data.</p><p>A changed form image owns its own colors. A missing form image means unavailable or unresolved—it must not be silently treated as the base palette. Layers and the shared projectile/FX template use the same numbered-set rule only when those domains exist.</p><p>Child palette variants may expand inside their relevant source set without a fixed limit. The extension records their parent explicitly; it does not guess a variant relationship from a filename.</p></div></details><p id="paletteLibraryPath" class="muted">No folder selected.</p><select id="paletteLibrarySelect" style="width:100%;margin:7px 0"><option>No ACT or indexed PNG palettes found</option></select><div class="palette-toolbar"><button id="choosePaletteLibrary" class="tool" title="Choose and remember a project folder containing ACT or indexed PNG palettes">Choose Folder…</button><button id="previewLibraryPalette" class="tool" title="Preview the selected library palette without changing the SFF">Preview Palette</button><button id="compareLibraryPalette" class="tool" title="Compare the selected library palette with the selected embedded SFF palette">Compare with Embedded</button><button id="stageLibraryPalette" class="tool" title="Stage this library palette under a new explicit SFF palette ID for the next SprMaker2 rebuild">Stage as New Palette…</button><button id="stagePaletteVariant" class="tool" title="Stage the selected library palette as an expandable child variant of the selected embedded palette">Stage as Child Variant…</button><button id="stagePaletteAlias" class="tool" title="Create a required palette coordinate that links to the selected embedded palette without owning duplicate colors">Stage Linked Alias…</button><button id="fillTransformAliases" class="tool" title="Fill missing transformation slots in this palette bank with linked aliases to the selected base palette">Fill Transform Slots</button><button id="reviewStagedPalettes" class="tool" title="Review or remove palettes staged for the next SprMaker2 rebuild">Review Staged…</button></div><div id="stagedPaletteStatus" class="status-list muted">No palettes staged for the next build.</div><p class="muted">Folders may contain any number of child variants. Linked aliases keep required RemapPal destinations such as 2,1 valid. The next palette-preserving SprMaker2 rebuild writes every declared coordinate and links identical color data.</p>';document.getElementById('palettePanel').append(paletteLibrary);document.getElementById('choosePaletteLibrary').onclick=()=>vscode.postMessage({type:'choosePaletteLibrary'});document.getElementById('previewLibraryPalette').onclick=()=>vscode.postMessage({type:'previewLibraryPalette',file:document.getElementById('paletteLibrarySelect').value});document.getElementById('compareLibraryPalette').onclick=()=>vscode.postMessage({type:'compareLibraryPalette',file:document.getElementById('paletteLibrarySelect').value,paletteIndex:Number(document.getElementById('paletteSelect').value)});document.getElementById('stageLibraryPalette').onclick=()=>vscode.postMessage({type:'stageLibraryPalette',file:document.getElementById('paletteLibrarySelect').value});document.getElementById('stagePaletteVariant').onclick=()=>vscode.postMessage({type:'stagePaletteVariant',file:document.getElementById('paletteLibrarySelect').value,paletteIndex:Number(document.getElementById('paletteSelect').value)});document.getElementById('stagePaletteAlias').onclick=()=>vscode.postMessage({type:'stagePaletteAlias',paletteIndex:Number(document.getElementById('paletteSelect').value)});document.getElementById('fillTransformAliases').onclick=()=>vscode.postMessage({type:'fillTransformAliases',paletteIndex:Number(document.getElementById('paletteSelect').value)});document.getElementById('reviewStagedPalettes').onclick=()=>vscode.postMessage({type:'reviewStagedPalettes'});vscode.postMessage({type:'paletteLibrary'});
  const insertPaletteButton=document.createElement('button');insertPaletteButton.id='insertPaletteShift';insertPaletteButton.className='tool';insertPaletteButton.textContent='Insert + Shift Later…';insertPaletteButton.title='Insert the selected library palette at an occupied or empty coordinate and shift later numbers in that group after an impact preview';document.getElementById('stagePaletteVariant').before(insertPaletteButton);insertPaletteButton.onclick=()=>vscode.postMessage({type:'insertPaletteShift',file:document.getElementById('paletteLibrarySelect').value,paletteIndex:Number(document.getElementById('paletteSelect').value)});window.addEventListener('message',event=>{if(event.data.type==='paletteLibraryList'){insertPaletteButton.disabled=!(event.data.items||[]).length;setTimeout(()=>{if((event.data.shifts||[]).length)document.getElementById('stagedPaletteStatus').textContent+=' | Pending shifts: '+event.data.shifts.map(shift=>shift.group+','+shift.start+' and later → +'+shift.amount).join(' · ')},0)}});
  const userLibrary=document.createElement('div');userLibrary.innerHTML='<hr><b>User-Created Palettes</b><details><summary><b>How user saves work</b></summary><div class="muted"><p>User-created colors are mutable player data, not project source palettes. Named saves live under <code>save/palettes/&lt;character&gt;/&lt;palette&gt;/</code>, so game updates do not overwrite them.</p><p>Each save contains <code>palette.act</code> plus <code>palette.json</code> recording its character, parent palette, fingerprint, and runtime bridge. Advanced characters can later add form, layer, and projectile/FX components to the same manifest.</p><p>IKEMEN still needs a palette path declared in the character DEF. Deploy copies the selected named save into that explicitly configured runtime slot. The extension never silently reserves <code>pal7</code> or another number.</p></div></details><p id="userPaletteContext" class="muted">Looking for the character DEF and runtime palette slot…</p><select id="userPaletteSelect" style="width:100%;margin:7px 0"><option>No user palettes saved</option></select><div class="palette-toolbar"><button id="saveUserPalette" class="tool" title="Save the currently displayed colors as a named, user-owned palette without changing project source palettes">Save Current As…</button><button id="previewUserPalette" class="tool" title="Preview the selected user palette without changing the SFF or runtime slot">Preview</button><button id="deployUserPalette" class="tool" title="Copy the selected named save into the character DEF runtime palette slot">Deploy to Game</button><button id="importRuntimePalette" class="tool" title="Preserve the current custom/user ACT runtime slot as a named user palette">Import Runtime Slot</button><button id="configureUserSlot" class="tool" title="Explicitly choose an unused DEF palette number and runtime ACT path; no number is reserved automatically">Configure Runtime Slot…</button><button id="openUserPaletteFolder" class="tool" title="Open this character user-palette save folder">Open Save Folder</button></div><div id="userPaletteStatus" class="status-list muted">No user palette operation has run.</div>';document.getElementById('palettePanel').append(userLibrary);document.getElementById('saveUserPalette').onclick=()=>vscode.postMessage({type:'saveUserPalette',paletteIndex:Number(document.getElementById('paletteSelect').value),colors:importedPaletteColors||displayedPaletteColors});document.getElementById('previewUserPalette').onclick=()=>vscode.postMessage({type:'previewUserPalette',id:document.getElementById('userPaletteSelect').value});document.getElementById('deployUserPalette').onclick=()=>vscode.postMessage({type:'deployUserPalette',id:document.getElementById('userPaletteSelect').value});document.getElementById('importRuntimePalette').onclick=()=>vscode.postMessage({type:'importRuntimePalette'});document.getElementById('configureUserSlot').onclick=()=>vscode.postMessage({type:'configureUserSlot',paletteIndex:Number(document.getElementById('paletteSelect').value),colors:importedPaletteColors||displayedPaletteColors});document.getElementById('openUserPaletteFolder').onclick=()=>vscode.postMessage({type:'openUserPaletteFolder'});vscode.postMessage({type:'userPaletteLibrary'});
  window.addEventListener('message',e=>{const m=e.data;if(m.type!=='userPaletteList')return;const select=document.getElementById('userPaletteSelect');select.textContent='';for(const item of m.items||[]){const option=document.createElement('option');option.value=item.id;option.textContent=item.name+(item.parent?' · child of '+item.parent:'');select.append(option)}if(!(m.items||[]).length){const option=document.createElement('option');option.value='';option.textContent='No user palettes saved';select.append(option)}const available=(m.items||[]).length>0;document.getElementById('previewUserPalette').disabled=!available;document.getElementById('deployUserPalette').disabled=!available;document.getElementById('userPaletteContext').textContent=(m.context.displayName||m.context.characterId)+' · '+(m.context.defPath?'DEF found':'DEF not found')+' · '+((m.context.runtimeSlots||[]).length?(m.context.runtimeSlots||[]).map(s=>'pal'+s.number+' → '+s.raw).join(' | '):'runtime slot not configured');document.getElementById('userPaletteStatus').textContent=m.root+' · '+(m.items||[]).length+' named save(s).'});
  document.getElementById('paletteFolderHelp').innerHTML='<summary><b>How palette folders work</b></summary><div class="muted"><p><b>Recommended palette-source layout:</b> Base contains every authored color. Each form folder, such as SSB or SSBE, contains only the numbered palettes whose colors actually change in that form. Keep the same palette number across forms so <code>001</code> remains the same community color.</p><p>An unchanged form does <b>not</b> need a duplicate PNG. Give its required SFF coordinate a reviewed linked alias, such as <code>2,1 → 1,1</code>. A changed form image owns independent colors. This keeps the source folders smaller while every gameplay RemapPal destination remains addressable without duplicate SFF color data.</p><p>A missing form image alone is unresolved—the extension will not guess whether it means unchanged or forgotten. Use <b>Fill Transform Slots</b> or stage an individual alias after confirming the color is unchanged. Missing-palette debug messages are not accepted as a completed IKEMEN setup.</p><p>Older HDBZ folders show the former image-import workflow and may omit matching form numbers because that project later tolerated debug messages. They explain the lineage, but they are not the new warning-free standard.</p><p>Layers and the shared projectile/FX template follow the same rule when those domains exist. Child variants may expand without a fixed limit, and their parent relationship is recorded explicitly rather than guessed from filenames.</p></div>';
  const previewPrefs=document.createElement('div');previewPrefs.innerHTML='<hr><b>Non-destructive Preview Palette</b><p id="previewPaletteStatus" class="muted"></p><div class="palette-toolbar"><button id="saveScreenPalette" class="tool" title="Use the selected palette by default throughout this SFF screen">Set for SFF Screen</button><button id="saveGroupPalette" class="tool" title="Use the selected palette whenever the current sprite group is displayed in SFF and AIR previews">Set for Current Group</button><button id="clearGroupPalette" class="tool" title="Remove the current group override and return to the screen default">Clear Group Override</button></div><p class="muted">Preview choices never rewrite sprite palette assignments. The character DEF pal.defaults value is used until a screen or group override is saved.</p>';document.getElementById('palettePanel').append(previewPrefs);function previewStatus(){const assigned=model.palettePreview.assignedDefault,p=model.palettes[model.palettePreview.screenPaletteIndex],g=selected&&model.palettePreview.groupPaletteIndices[String(selected.group)],gp=model.palettes[g];document.getElementById('previewPaletteStatus').textContent='DEF default: '+assigned.group+','+assigned.number+' · SFF screen: '+(p?p.group+','+p.number:'sprite palette')+(selected?' · Group '+selected.group+': '+(gp?gp.group+','+gp.number:'inherits screen'):'')}document.getElementById('saveScreenPalette').onclick=()=>vscode.postMessage({type:'setPreviewPalette',scope:'screen',paletteIndex:Number(document.getElementById('paletteSelect').value)});document.getElementById('saveGroupPalette').onclick=()=>{if(selected)vscode.postMessage({type:'setPreviewPalette',scope:'group',group:selected.group,paletteIndex:Number(document.getElementById('paletteSelect').value)})};document.getElementById('clearGroupPalette').onclick=()=>{if(selected)vscode.postMessage({type:'clearGroupPreviewPalette',group:selected.group})};
  function showMasterStatus(status){const target=document.getElementById('masterStatus');if(!status.exists){target.textContent='No protected master exists for this SFF.';return}const c=status.comparison;if(!c){target.textContent='Protected master found: '+status.file;return}if(c.exact)target.textContent='MASTER MATCH · palette and '+status.indexedCount+' protected indexed sprites match.';else target.textContent='MASTER DIFFERENCE · '+(c.paletteMissing?'palette missing; ':'')+(c.paletteChanged?'palette colors changed; ':'')+c.changedIndexData.length+' index-data change(s); '+c.changedPaletteAssignments.length+' palette-assignment change(s); '+c.missingSprites.length+' missing protected sprite(s); '+c.addedSprites.length+' new indexed sprite(s).'}
  function showPaletteAudit(audit){const target=document.getElementById('paletteAudit');target.textContent='';const heading=document.createElement('div');heading.textContent=(audit.exact?'PASS':'REVIEW')+' · '+audit.paletteCount+' palette(s) · '+audit.indexedSpriteCount+' indexed sprite(s)';target.append(heading);if(!audit.issues.length){const row=document.createElement('div');row.textContent='No palette setup problems found.';target.append(row);return}for(const issue of audit.issues){const row=document.createElement('div');row.textContent=issue.severity.toUpperCase()+' · '+issue.message;target.append(row)}}
  function requestPaletteData(index){if(!Number.isInteger(Number(index)))return;vscode.postMessage({type:'palette',paletteIndex:Number(index)})}
