  const targets = await chooseSpriteScope(archive, message, `${action} — choose sprite scope`); if (!targets.length) return;
  const destination = await vscode.window.showOpenDialog({ title: 'Choose an output folder', canSelectFiles: false, canSelectFolders: true, canSelectMany: false }); if (!destination || !destination[0]) return;
  let filter = '', suffix = action;
  if (action === 'resize') { const value = await vscode.window.showInputBox({ title: 'Resize percentage', prompt: 'Enter a percentage such as 200 or 50.', value: '200', validateInput: (v) => /^\d+(?:\.\d+)?$/.test(v) && Number(v) > 0 ? undefined : 'Enter a positive percentage.' }); if (!value) return; filter = `scale=iw*${Number(value) / 100}:ih*${Number(value) / 100}:flags=neighbor`; suffix = `resize_${value}pct`; }
  if (action === 'crop') { const value = await vscode.window.showInputBox({ title: 'Crop rectangle', prompt: 'Enter width,height,x,y.', value: '64,64,0,0', validateInput: (v) => /^\d+\s*,\s*\d+\s*,\s*\d+\s*,\s*\d+$/.test(v) ? undefined : 'Enter width,height,x,y.' }); if (!value) return; const [w, h, x, y] = value.split(',').map(Number); filter = `crop=${w}:${h}:${x}:${y}`; }
  if (action === 'rotate') { const value = await vscode.window.showQuickPick([{ label: '90° clockwise', filter: 'transpose=1', suffix: 'rotate_cw' }, { label: '90° counter-clockwise', filter: 'transpose=2', suffix: 'rotate_ccw' }, { label: '180°', filter: 'hflip,vflip', suffix: 'rotate_180' }], { title: 'Rotation' }); if (!value) return; filter = value.filter; suffix = value.suffix; }
  const temp = fs.mkdtempSync(path.join(os.tmpdir(), 'ikemen-sff-process-'));
  await vscode.window.withProgress({ location: vscode.ProgressLocation.Notification, title: `${action}: processing ${targets.length} sprite(s)` }, async () => { for (const sprite of targets) { const base = `g${String(sprite.group).padStart(5, '0')}_i${String(sprite.number).padStart(5, '0')}`, input = path.join(temp, `${base}.png`), output = path.join(destination[0].fsPath, `${base}_${suffix}.png`); fs.writeFileSync(input, spritePng(archive, sprite)); runFfmpeg(['-i', input, '-vf', filter, output]); } }); vscode.window.showInformationMessage(`${action} created ${targets.length} non-destructive PNG output(s).`);
